async def _record_job_spans(executor: RemoteExecutor, run_command: Callable[..., object]) -> None:
    """Record what each job of the sync that just ran cost, read off that run's own log.

    A sync is one command to the test, so without this the biggest single cost in the suite
    is also the most opaque. Jobs execute sequentially (`_run_jobs_in_task_group`), so the
    span from a job's first log line to its last is that job's own time.

    `run_command` is the UNPATCHED method: reading the log is measurement, not work the suite
    would otherwise do, and it must not recurse into the wrapper that called this.
    """
    try:
        result = await run_command(executor, _NEWEST_SYNC_LOG, timeout=30.0, login_shell=False)  # pyright: ignore[reportAny]
        lines = str(result.stdout).splitlines()  # pyright: ignore[reportAny]
    except Exception:
        return  # a run whose log is already gone still has its command timings

